   957	struct morx
   958	{
   959	  static const hb_tag_t tableTag = HB_AAT_TAG_morx;
   960	
   961	  inline bool has_data (void) const { return version != 0; }
   962	
   963	  inline void apply (hb_aat_apply_context_t *c) const
   964	  {
   965	    if (unlikely (!c->buffer->successful)) return;
   966	    c->set_lookup_index (0);
   967	    const Chain *chain = &firstChain;
   968	    unsigned int count = chainCount;
   969	    for (unsigned int i = 0; i < count; i++)
   970	    {
   971	      chain->apply (c);
   972	      if (unlikely (!c->buffer->successful)) return;
   973	      chain = &StructAfter<Chain> (*chain);
   974	    }
   975	  }
   976	
   977	  inline bool sanitize (hb_sanitize_context_t *c) const
   978	  {
   979	    TRACE_SANITIZE (this);
   980	    if (!version.sanitize (c) || version < 2 ||
   981	        !chainCount.sanitize (c))
   982	      return_trace (false);
   983	
   984	    const Chain *chain = &firstChain;
   985	    unsigned int count = chainCount;
   986	    for (unsigned int i = 0; i < count; i++)
   987	    {
   988	      if (!chain->sanitize (c, version))
   989	        return_trace (false);
   990	      chain = &StructAfter<Chain> (*chain);
   991	    }
   992	
   993	    return_trace (true);
   994	  }
   995	
   996	  protected:
   997	  HBUINT16      version;        /* Version number of the glyph metamorphosis table.
   998	                                 * 2 or 3. */
   999	  HBUINT16      unused;         /* Set to 0. */
  1000	  HBUINT32      chainCount;     /* Number of metamorphosis chains contained in this
  1001	                                 * table. */
  1002	  Chain         firstChain;     /* Chains. */
  1003	
  1004	  public:
  1005	  DEFINE_SIZE_MIN (8);
  1006	};
